/**
 * OpenAI text-to-speech via the Realtime API.
 *
 * OpenAI shuts down the /v1/audio/speech models (gpt-4o-mini-tts, tts-1,
 * tts-1-hd) on 2027-01-06. Their replacement, gpt-realtime-2.1-mini, is only
 * available through the Realtime API, so speech is generated by opening a
 * short-lived Realtime WebSocket session, asking the model to read the text
 * verbatim, and collecting the streamed PCM audio.
 *
 * The Realtime API only outputs raw 16-bit mono PCM at 24 kHz, which is wrapped
 * in a WAV container so Sonos can play it.
 */

const DEFAULT_REALTIME_TTS_MODEL = 'gpt-realtime-2.1-mini';
const DEFAULT_REALTIME_TTS_VOICE = 'marin';
const PCM_SAMPLE_RATE = 24000;
const DEFAULT_TIMEOUT_MS = 30000;

const REALTIME_VOICES = new Set([
  'alloy', 'ash', 'ballad', 'coral', 'echo', 'sage', 'shimmer', 'verse', 'marin', 'cedar'
]);

// Models served only by /v1/audio/speech, all shut down by OpenAI on 2027-01-06.
const LEGACY_SPEECH_MODEL_PATTERN = /^(tts-1(-hd)?|gpt-4o-mini-tts)(-\d{4}-\d{2}-\d{2})?$/i;

const VERBATIM_INSTRUCTIONS =
  'You are a text-to-speech engine. Read the user\'s message aloud exactly as written, ' +
  'word for word, in the language it is written in. Do not answer it, comment on it, ' +
  'translate it, add greetings, or say anything else. A "..." means a short pause.';

function isLegacySpeechModel(model) {
  return LEGACY_SPEECH_MODEL_PATTERN.test(String(model || '').trim());
}

/**
 * Resolve the configured model to a Realtime model. Legacy /v1/audio/speech
 * models are mapped to the default Realtime model so existing configs keep
 * working after OpenAI's shutdown.
 */
function resolveRealtimeTtsModel(model) {
  const trimmed = String(model || '').trim();
  if (!trimmed || isLegacySpeechModel(trimmed)) {
    return { model: DEFAULT_REALTIME_TTS_MODEL, replaced: trimmed || null };
  }
  return { model: trimmed, replaced: null };
}

/**
 * Resolve the configured voice to one the Realtime API supports. Voices only
 * offered by the old speech models (fable, onyx, nova) fall back to the default.
 */
function resolveRealtimeTtsVoice(voice) {
  const trimmed = String(voice || '').trim().toLowerCase();
  if (REALTIME_VOICES.has(trimmed)) {
    return { voice: trimmed, replaced: null };
  }
  return { voice: DEFAULT_REALTIME_TTS_VOICE, replaced: trimmed || null };
}

/** Realtime output speed is limited to 0.25–1.5. */
function clampRealtimeSpeed(speed) {
  const value = Number(speed);
  if (!Number.isFinite(value)) return 1;
  return Math.min(1.5, Math.max(0.25, value));
}

function buildSessionUpdate({ model, voice, speed, instructions }) {
  const extra = String(instructions || '').trim();
  return {
    type: 'session.update',
    session: {
      type: 'realtime',
      model,
      output_modalities: ['audio'],
      instructions: extra
        ? `${VERBATIM_INSTRUCTIONS}\nVoice direction: ${extra}`
        : VERBATIM_INSTRUCTIONS,
      audio: {
        input: { turn_detection: null },
        output: {
          format: { type: 'audio/pcm', rate: PCM_SAMPLE_RATE },
          voice,
          speed: clampRealtimeSpeed(speed)
        }
      }
    }
  };
}

function defaultCreateConnection(client, model) {
  // Lazy-load so the rest of the app does not depend on the realtime entrypoint.
  const { OpenAIRealtimeWS } = require('openai/realtime/ws');
  return new OpenAIRealtimeWS({ model }, client);
}

/**
 * Generate speech for `text` and return raw 16-bit mono PCM at 24 kHz.
 *
 * @param {object} opts
 * @param {object} opts.client OpenAI client (supplies API key and base URL)
 * @param {string} opts.text Text to speak
 * @param {string} opts.model Realtime model id
 * @param {string} opts.voice Realtime voice
 * @param {number} [opts.speed]
 * @param {string} [opts.instructions] Optional voice direction
 * @param {number} [opts.timeoutMs]
 * @param {Function} [opts.createConnection] (client, model) => realtime connection; for tests
 * @returns {Promise<Buffer>}
 */
function synthesizeRealtimeSpeech(opts) {
  const {
    client,
    text,
    model,
    voice,
    speed = 1,
    instructions = '',
    timeoutMs = DEFAULT_TIMEOUT_MS,
    createConnection = defaultCreateConnection
  } = opts;

  if (!text || !String(text).trim()) {
    return Promise.reject(new Error('No text to synthesize'));
  }

  return new Promise((resolve, reject) => {
    let rt;
    let settled = false;
    const chunks = [];

    const finish = (err, result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try {
        if (rt) rt.close();
      } catch (_) {
        // ignore close failures; the result is already decided
      }
      if (err) reject(err);
      else resolve(result);
    };

    const timer = setTimeout(() => {
      finish(new Error(`OpenAI Realtime TTS timed out after ${timeoutMs}ms`));
    }, timeoutMs);

    try {
      rt = createConnection(client, model);
    } catch (err) {
      finish(err);
      return;
    }

    rt.on('error', (err) => {
      const message = (err && err.error && err.error.message) || (err && err.message) || String(err);
      finish(new Error(`OpenAI Realtime TTS error: ${message}`));
    });

    rt.on('response.output_audio.delta', (event) => {
      if (event && event.delta) {
        chunks.push(Buffer.from(event.delta, 'base64'));
      }
    });

    rt.on('response.done', (event) => {
      const response = event && event.response;
      if (response && response.status && response.status !== 'completed') {
        const detail = response.status_details && (response.status_details.reason ||
          (response.status_details.error && response.status_details.error.message));
        finish(new Error(`OpenAI Realtime TTS response ${response.status}${detail ? `: ${detail}` : ''}`));
        return;
      }
      const pcm = Buffer.concat(chunks);
      if (pcm.length === 0) {
        finish(new Error('OpenAI Realtime TTS returned no audio'));
        return;
      }
      finish(null, pcm);
    });

    const start = () => {
      rt.send(buildSessionUpdate({ model, voice, speed, instructions }));
      rt.send({
        type: 'conversation.item.create',
        item: {
          type: 'message',
          role: 'user',
          content: [{ type: 'input_text', text: String(text) }]
        }
      });
      rt.send({ type: 'response.create' });
    };

    if (rt.socket && typeof rt.socket.on === 'function' && rt.socket.readyState !== 1) {
      rt.socket.on('open', start);
      rt.socket.on('close', (code) => {
        finish(new Error(`OpenAI Realtime TTS connection closed (code ${code})`));
      });
    } else {
      start();
    }
  });
}

/** Wrap raw 16-bit little-endian PCM in a WAV (RIFF) container. */
function pcmToWav(pcm, sampleRate = PCM_SAMPLE_RATE, channels = 1) {
  const bitsPerSample = 16;
  const byteRate = sampleRate * channels * bitsPerSample / 8;
  const blockAlign = channels * bitsPerSample / 8;
  const header = Buffer.alloc(44);
  header.write('RIFF', 0, 'ascii');
  header.writeUInt32LE(36 + pcm.length, 4);
  header.write('WAVE', 8, 'ascii');
  header.write('fmt ', 12, 'ascii');
  header.writeUInt32LE(16, 16);
  header.writeUInt16LE(1, 20);
  header.writeUInt16LE(channels, 22);
  header.writeUInt32LE(sampleRate, 24);
  header.writeUInt32LE(byteRate, 28);
  header.writeUInt16LE(blockAlign, 32);
  header.writeUInt16LE(bitsPerSample, 34);
  header.write('data', 36, 'ascii');
  header.writeUInt32LE(pcm.length, 40);
  return Buffer.concat([header, pcm]);
}

/** Duration in seconds of a WAV buffer produced by pcmToWav. */
function wavDurationSeconds(wav) {
  if (!Buffer.isBuffer(wav) || wav.length < 44 || wav.toString('ascii', 0, 4) !== 'RIFF') {
    throw new Error('Not a WAV buffer');
  }
  const byteRate = wav.readUInt32LE(28);
  const dataLength = wav.readUInt32LE(40);
  if (!byteRate) throw new Error('Invalid WAV byte rate');
  return dataLength / byteRate;
}

module.exports = {
  DEFAULT_REALTIME_TTS_MODEL,
  DEFAULT_REALTIME_TTS_VOICE,
  REALTIME_VOICES,
  isLegacySpeechModel,
  resolveRealtimeTtsModel,
  resolveRealtimeTtsVoice,
  clampRealtimeSpeed,
  buildSessionUpdate,
  synthesizeRealtimeSpeech,
  pcmToWav,
  wavDurationSeconds
};
